#version 430

const int MAX_LIGHTS = 8;

layout(location = 0) in vec3 aPosition;
layout(location = 1) in vec2 aUV;
layout(location = 2) in vec3 aNormal;
layout(location = 3) uniform mat4 MVP;
layout(location = 4) uniform mat4 model;
layout(location = 5) in vec3 aTangent;
layout(location = 6) in vec3 aBitangent;
layout(location = 7) uniform mat4 aView;
layout(location = 8) uniform mat4 lightVP[MAX_LIGHTS];

out vec2 uv;
out vec3 normal;
out vec3 fragPos;

uniform int numLights;

out vec3 tangent;
out vec3 bitangent;

out vec4 fragPosLight[MAX_LIGHTS];

out vec3 localPos;
out vec3 localNormal;

void main() {

    localPos = aPosition;

    localNormal= aNormal;

    gl_Position = MVP * vec4(aPosition, 1.0);

    for(int i=0; i < numLights; i++)
        fragPosLight[i] = lightVP[i] * model * vec4(aPosition,1.0); // transform it to light space

    uv = aUV;

    fragPos = vec3(aView * model * vec4(aPosition, 1.0));

    mat3 normalMatrix = transpose(inverse(mat3(aView * model)));

    normal = normalize(normalMatrix * aNormal);

    tangent = normalize(normalMatrix * aTangent);

    bitangent = normalize(normalMatrix * aBitangent);

}

#version 430

const int MAX_LIGHTS = 8;

struct Light {

    int type; // 0 = POINT, 1 = DIR, 2 = SPOT

    vec3 position;
    vec3 direction;
    vec3 color;

    vec3 attenuation;

    float ambient;

    float bias;
    float pcf;

    float inner;
    float outer;
    float falloff;
};

uniform int numLights;
uniform Light lights[MAX_LIGHTS];

uniform sampler2D tex;

uniform bool useTexture;
uniform vec3 color;

uniform sampler2D normalMap;
uniform sampler2D roughnessMap;
uniform sampler2D metallicMap;
uniform sampler2D emissionMap;
uniform sampler2D opacityMap;
uniform sampler2D depthData[MAX_LIGHTS];

uniform bool hasNormalMap;
uniform bool hasRoughnessMap;
uniform bool hasMetallicMap;
uniform bool packedMetallicRoughnessMap;
uniform bool hasEmissionMap;
uniform bool hasOpacityMap;
uniform float materialRoughness;
uniform float materialMetallic;
uniform vec3 materialEmission;
uniform float materialOpacity;

uniform bool light_active;
uniform bool normal_map_active;
uniform bool shadow_active;

uniform mat4 aView;

uniform vec2 textureTiling;

uniform int mapping;

uniform vec3 objMin;
uniform vec3 objMax;

uniform vec3 worldSize;

uniform bool tiling;
uniform bool renderBothSides;

in vec2 uv;
in vec3 normal;
in vec3 fragPos;

in vec3 localPos;
in vec3 localNormal;

in vec3 tangent;
in vec3 bitangent;

out vec4 outputColor;

// light
in vec4 fragPosLight[MAX_LIGHTS];

// Shadow factor of a spot light: 0.0 = lit, 1.0 = fully in shadow.
// Only called once the pixel is known to be inside the cone and facing the light.
float CalcShadow(int i, Light light) {

    vec3 proj = fragPosLight[i].xyz / fragPosLight[i].w;

    vec3 norm_proj = proj * 0.5 + 0.5;

    if (norm_proj.x < 0.0 || norm_proj.x > 1.0 || norm_proj.y < 0.0 || norm_proj.y > 1.0 || norm_proj.z > 1.0)
        return 0.0;

    float currentDepth = norm_proj.z;

    vec2 texelSize = 1.0 / vec2(textureSize(depthData[i], 0));

    int radius = int(light.pcf);

    float shadow = 0.0;

    for (int x = -radius; x <= radius; x++) {

        for (int y = -radius; y <= radius; y++) {

            float depth = texture(depthData[i], norm_proj.xy + vec2(x, y) * texelSize).r;

            if (currentDepth - light.bias > depth)
                shadow += 1.0;
        }
    }

    int samples = (2 * radius + 1) * (2 * radius + 1);

    return shadow / float(samples);
}

vec3 ShadePointLight(Light light, vec3 N, vec3 V, vec3 baseColor, float specPower, float metallic) {

    vec3 lightPosView = vec3(aView * vec4(light.position, 1.0));

    vec3 Lvec = lightPosView - fragPos;
    float dist = length(Lvec);
    vec3 L = normalize(Lvec);

    float diff = max(dot(N, L), 0.0);

    float denom = light.attenuation.x + light.attenuation.y * dist + light.attenuation.z * dist * dist;

    float att = 1.0 / max(denom, 0.0001);

    vec3 R = reflect(-L, N);
    float spec = pow(max(dot(V, R), 0.0), specPower);

    vec3 diffuse = diff * light.color * min(att, 1.0);
    vec3 specular = spec * mix(vec3(0.04), baseColor, metallic) * light.color * min(att, 1.0);

    return (light.ambient * light.color * baseColor) + ((diffuse * baseColor) + specular);
}

vec3 ShadeDirLight(Light light, vec3 N, vec3 V, vec3 baseColor, float specPower, float metallic) {

    vec3 dirView = normalize(mat3(aView) * light.direction);

    vec3 L = normalize(-dirView);

    float diff = max(dot(N, L), 0.0);

    vec3 R = reflect(-L, N);
    float spec = pow(max(dot(V, R), 0.0), specPower);

    vec3 diffuse = diff * light.color;
    vec3 specular = spec * mix(vec3(0.04), baseColor, metallic) * light.color;

    return (light.ambient * light.color * baseColor) + ((diffuse * baseColor) + specular);
}

vec3 ShadeSpotLight(int i, Light light, vec3 N, vec3 V, vec3 baseColor, float specPower, float metallic) {

    vec3 lightPosView = vec3(aView * vec4(light.position, 1.0));

    vec3 Lvec = lightPosView - fragPos;

    float dist = length(Lvec);

    vec3 L = normalize(Lvec);

    vec3 dirView = normalize(mat3(aView) * light.direction);

    float alpha = dot(-L, dirView);

    float phi = cos(radians(light.outer));
    float theta = cos(radians(light.inner));

    vec3 diffuse;
    vec3 specular;

    if(alpha < phi)
        return light.ambient * light.color * baseColor;

    float spotEff = 1.0f;

    if(alpha < theta)
        spotEff = clamp(pow((alpha - phi) / (theta - phi), light.falloff), 0.0, 1.0);

    float diff = max(dot(N, L), 0.0);

    // facing away from the light: only ambient, no shadow lookup needed
    if(diff <= 0.0)
        return light.ambient * light.color * baseColor;

    float shadow = shadow_active ? CalcShadow(i, light) : 0.0;

    float denom = light.attenuation.x + light.attenuation.y * dist + light.attenuation.z * dist * dist;

    float att = 1.0 / max(denom, 0.0001);

    vec3 R = reflect(-L, N);

    float spec = pow(max(dot(V, R), 0.0), specPower);

    diffuse = diff * light.color * min(att, 1.0) * spotEff;

    specular = spec * mix(vec3(0.04), baseColor, metallic) * light.color * min(att, 1.0) * spotEff;

    return (light.ambient * light.color * baseColor) + (1.0 - shadow) * ((diffuse * baseColor) + specular);
}

void main() {

    // ------------------------------------------------------------
    // uv

    vec2 tiledUV;

    if (tiling) {

        vec2 mappedUV;
        vec2 tilingValue;

        vec3 p = localPos;
        vec3 Na = normalize(localNormal);

        vec3 size = max(objMax - objMin, vec3(0.000001));

        vec3 normalizedPos = (p - objMin) / size;

        vec3 absN = abs(Na);

        if (mapping == 2) {

            if (absN.x >= absN.y && absN.x >= absN.z) {

                mappedUV = normalizedPos.zy;
                tilingValue = worldSize.zy;

            } else if (absN.y >= absN.x && absN.y >= absN.z) {

                mappedUV = normalizedPos.xz;
                tilingValue = worldSize.xz;

            } else {

                mappedUV = normalizedPos.xy;
                tilingValue = worldSize.xy;
            }

        } else {

            mappedUV = uv;
            tilingValue = textureTiling;
        }

        tiledUV = mappedUV * tilingValue;
    }
    else
        tiledUV = uv;


    // ------------------------------------------------------------
    // albedo

    vec3 baseColor = color;

    float alpha = 1.0;

    if (useTexture) {

        vec4 texColor = texture(tex, tiledUV);

        alpha = texColor.a;

        if (alpha < 0.1)
            discard;

        baseColor = texColor.rgb * color;
    }

    float roughness = clamp(materialRoughness, 0.04, 1.0);

    if (hasRoughnessMap) {
        vec4 roughnessSample = texture(roughnessMap, tiledUV);
        roughness *= packedMetallicRoughnessMap ? roughnessSample.g : roughnessSample.r;
        roughness = clamp(roughness, 0.04, 1.0);
    }

    float metallic = clamp(materialMetallic, 0.0, 1.0);

    if (hasMetallicMap) {
        vec4 metallicSample = texture(metallicMap, tiledUV);
        metallic *= packedMetallicRoughnessMap ? metallicSample.b : metallicSample.r;
        metallic = clamp(metallic, 0.0, 1.0);
    }

    vec3 emission = materialEmission;

    if (hasEmissionMap)
        emission *= texture(emissionMap, tiledUV).rgb;

    alpha *= materialOpacity;

    if (hasOpacityMap)
        alpha *= texture(opacityMap, tiledUV).r;

    if (alpha < 0.1)
        discard;


    // ------------------------------------------------------------
    // normal

    vec3 N = normalize(normal);

    if (renderBothSides && !gl_FrontFacing)
        N = -N;

    vec3 finalNormal = N;


    if (hasNormalMap && normal_map_active) {

        vec3 T = normalize(tangent);

        T = normalize(T - N * dot(N, T));

        vec3 B = normalize(cross(N, T));

        mat3 TBN = mat3(T, B, N);


        vec3 normalTS = texture(normalMap, tiledUV).xyz;

        normalTS = normalTS * 2.0 - 1.0;

        finalNormal = normalize(TBN * normalTS);
    }


    // ------------------------------------------------------------
    // cam

    vec3 V = normalize(-fragPos);


    if (!light_active) {

        outputColor = vec4(baseColor + emission, alpha);

        return;
    }


    // ------------------------------------------------------------
    // light

    vec3 result = emission;
    float specPower = mix(256.0, 2.0, roughness);


    for (int i = 0; i < numLights; i++) {

        if (lights[i].type == 0)
            result += ShadePointLight(lights[i], finalNormal, V, baseColor, specPower, metallic);
        else if (lights[i].type == 1)

            result += ShadeDirLight(lights[i], finalNormal, V, baseColor, specPower, metallic);
        else if (lights[i].type == 2)

            result += ShadeSpotLight(i, lights[i], finalNormal, V, baseColor, specPower, metallic);
    }


    outputColor = vec4(result, alpha);
}

#version 430

layout(location = 0) in vec3 aPosition;
layout(location = 3) uniform mat4 MVP;

void main() {

    gl_Position = MVP * vec4(aPosition, 1.0);
}

#version 430

uniform vec3 color;
out vec4 outputColor;

void main() {

    outputColor = vec4(color, 1.0);
}

#version 330 core

layout(location=0) in vec3 aPos;

out vec3 TexCoords;

uniform mat4 projection;
uniform mat4 view;

void main() {

    TexCoords = aPos;

    vec4 pos = projection * view * vec4(aPos,1.0);

    gl_Position = pos.xyww;
}

#version 330 core

in vec3 TexCoords;

out vec4 FragColor;

uniform samplerCube skybox;

uniform bool is_hdr;

void main() {

    if(is_hdr)
        FragColor = texture(skybox, -TexCoords);
    else
        FragColor = texture(skybox, TexCoords);
}

uniform mat4 ProjMtx;
in vec2 Position;
in vec2 UV;
in vec4 Color;
out vec2 Frag_UV;
out vec4 Frag_Color;
void main()
{
    Frag_UV = UV;
    Frag_Color = Color;
    gl_Position = ProjMtx * vec4(Position.xy,0,1);
}

uniform sampler2D Texture;
in vec2 Frag_UV;
in vec4 Frag_Color;
out vec4 Out_Color;
void main()
{
    Out_Color = Frag_Color * texture(Texture, Frag_UV.st);
}
